import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Стоматология: онлайн-запись к врачам и кабинет пациента"}>
      <p>{"Стоматологическая клиника в Казани, пять врачей: терапевт, два хирурга, ортодонт и детский стоматолог. Хотим, чтобы пациенты записывались к врачам онлайн, а администратор сразу узнавал о новых записях. Пациент выбирает услугу или врача, видит свободное время и записывается; за день до приёма ему приходит напоминание. В личном кабинете пациент видит свои записи и может перенести или отменить запись не позже чем за 12 часов. Врач видит только своё расписание, администратор — всё и может записать пациента по звонку. Нужен и сайт клиники: услуги с ценами «от», врачи с фото и опытом, отзывы, контакты и как доехать. Администратор у нас клиент, он пишет нам в телеграм клиент — пусть уведомления о записях приходят ему на почту. Медицинские карты на сайте не ведём — только запись."}</p>
      <ul>
        <li>{"Онлайн-запись на свободное время"}</li>
        <li>{"Напоминание за день"}</li>
        <li>{"Кабинет пациента"}</li>
        <li>{"Перенос и отмена записи"}</li>
      </ul>
      <p>{"Врач видит только своё расписание"}</p>
      <p>{"Администратор узнаёт о новой записи"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
